												if(siteName != "" && locationName != "")
												{
													input.Delivery_To = siteName + " - " + locationName;
												}
												else if(siteName != "")
												{
													input.Delivery_To = siteName;
												}
												else
												{
													input.Delivery_To = locationName;
												}
											}
											else
											{
												input.Delivery_To = locationName;
											}
										}
										else
										{
											if(input.Site_To != null)
											{
												input.Delivery_To = ifnull(input.Site_To.Display_Name_Asset_Name,"").toString().trim();
											}
											else
											{
												input.Delivery_To = "";
											}
										}

// ======================================
										// TRUCK MOVEMENT VOUCHER - FINALIZE
										// CREATED OR EDITED
										// ======================================
										info "===== TRUCK MOVEMENT VOUCHER FINALIZE START =====";
										is_create = false;
										if(input.Added_Time != null && input.Modified_Time != null)
										{
											if(input.Added_Time.toLong() == input.Modified_Time.toLong())
											{
												is_create = true;
											}
										}
										status_before = ifnull(input.Truck_Movement_Voucher_Status,"").trim();
										run_delivered_processing = false;
										delivered_processing_ok = true;
										// =====================================================
										// 2. CANCELLATION
										// =====================================================
										if(input.Cancel_Voucher == true)
										{
											input.Truck_Movement_Voucher_Status = "Cancelled";
											input.Line_Duration_Minutes = 0;
											input.Line_Distance_Travelled = 0;
											info "Truck Movement Voucher cancelled.";
										}
										else
										{
											// =====================================================
											// 3. CREATE MODE
											// =====================================================
											if(is_create)
											{
												if(input.Time_Start == null)
												{
													input.Time_Start = zoho.currenttime;
												}
												input.Truck_Movement_Voucher_Status = "In Progress";
												input.Truck_Movement = false;
												truck_plate_key = ifnull(input.Number_Plate_Truck_Register,"").trim();
												if(truck_plate_key != "")
												{
													previousAvailableTrips = Truck_Movement_Voucher[ID != input.ID && Number_Plate_Truck_Register == truck_plate_key && Truck_Movement == true];
													for each  previousTrip in previousAvailableTrips
													{
														previousTrip.Truck_Movement=false;
													}
													info "Previous available trip disabled for truck: " + truck_plate_key;
												}
												info "CREATE MODE: Time Start set and status moved to In Progress.";
											}
											else
											{
												if(input.Time_Start != null && input.Time_End != null)
												{
													diffMillis = input.Time_End.toLong() - input.Time_Start.toLong();
													duration_min = diffMillis / (1000 * 60);
													if(duration_min < 0)
													{
														duration_min = 0;
													}
													input.Line_Duration_Minutes = round(duration_min,2);
												}
												else
												{
													input.Line_Duration_Minutes = 0;
												}
												if(input.Odometer_Start != null && input.Odometer_End != null)
												{
													distance = input.Odometer_End - input.Odometer_Start;
													if(distance < 0)
													{
														distance = 0;
													}
													input.Line_Distance_Travelled = round(distance,2);
												}
												else
												{
													input.Line_Distance_Travelled = 0;
												}
												has_services = false;
												service_rows_count = 0;
												for each  srv in input.Services
												{
													if(srv.Service != null)
													{
														has_services = true;
														service_rows_count = service_rows_count + 1;
													}
												}
												if(input.Job != null)
												{
													job_number = ifnull(input.Job.Job_No,"").trim();
													if(job_number == "TJS01")
													{
														if(status_before == "Delivered" && has_services == true)
														{
															run_delivered_processing = true;
															info "TJS01: Delivered record has services. Running final processing.";
														}
														else if(input.Time_End != null)
														{
															input.Truck_Movement_Voucher_Status = "Delivered";
															info "TJS01: Time End entered. Status moved to Delivered.";
														}
														else
														{
															input.Truck_Movement_Voucher_Status = "In Progress";
															info "TJS01: Waiting for Time End.";
														}
													}
													/*
													else if(job_number == "TJS03")
													{
														if(input.Tractor_Work_Report != null)
														{
															twr = Tractor_Work_Report[ID == input.Tractor_Work_Report];
															if(twr.ID != null && twr.Tractor_Work_Report_Status == "Loaded")
															{
																twr.Tractor_Work_Report_Status="Completed";
															}
														}
														if(status_before == "Delivered" && has_services == true)
														{
															run_delivered_processing = true;
														}
														else if(input.Time_End != null)
														{
															input.Truck_Movement_Voucher_Status = "Delivered";
														}
														else
														{
															input.Truck_Movement_Voucher_Status = "In Progress";
														}
													}
												*/
													// =================================================
													// TJS04
													// =================================================
													else if(job_number == "TJS04")
													{
														input.Truck_Movement_Voucher_Status = "Completed";
														if(input.Truck_Movement_Voucher != null)
														{
															oldMove = Truck_Movement_Voucher[ID == input.Truck_Movement_Voucher];
															if(oldMove.ID != null && oldMove.Truck_Movement_Voucher_Status == "Delivered")
															{
																oldMove.Truck_Movement_Voucher_Status="Completed";
															}
														}
													}
													// =================================================
													// OTHER JOBS
													// =================================================
													else
													{
														if(status_before == "Delivered" && has_services == true)
														{
															run_delivered_processing = true;
														}
														else if(input.Time_End != null)
														{
															input.Truck_Movement_Voucher_Status = "Delivered";
														}
														else
														{
															input.Truck_Movement_Voucher_Status = "In Progress";
														}
													}
												}
												// =====================================================
												// 7. RUN ALL DELIVERED PROCESSING
												// =====================================================
												if(run_delivered_processing == true)
												{
													info "===== DELIVERED PROCESSING START =====";
													offloading_total = 0.0;
													existing_bill_id = null;
													for each  srv in input.Services
													{
														if(srv.Service != null)
														{
															service_name = ifnull(srv.Service.Service_Name,"").trim();
															if(service_name == "Offloading")
															{
																offloading_total = offloading_total + ifnull(srv.Line_Total,0.0);
																if(existing_bill_id == null && srv.Bill != null)
																{
																	existing_bill_id = srv.Bill.ID;
																}
															}
														}
													}
													if(offloading_total > 0)
													{
														employee_vendor_result = employee_management.employee.get_employee_by_display_name("Richard Lubega - 8");
														employee_vendor_id = null;
														employee_vendor_display = "";
														if(employee_vendor_result != null && ifnull(employee_vendor_result.get("ok"),false) == true)
														{
															employee_vendor_id = employee_vendor_result.get("employee_id");
															employee_vendor_display = ifnull(employee_vendor_result.get("display_name"),"Richard Lubega - 8");
														}
														else
														{
															delivered_processing_ok = false;
															info "Offloading employee vendor was not found.";
														}
														if(employee_vendor_id != null)
														{
															bill_id = null;
															bill_number = "";
															bill_date = zoho.currentdate;
															if(input.Time_Start != null)
															{
																bill_date = input.Time_Start.toDate();
															}
															existing_bill = null;
															if(existing_bill_id != null)
															{
																existing_bill = Bill[ID == existing_bill_id];
															}
															if(existing_bill != null && existing_bill.ID != null && ifnull(existing_bill.Bill_Name,"").trim() == "Offloading")
															{
																paid_amount = ifnull(existing_bill.Amount_Paid,0.0);
																balance_amount = offloading_total - paid_amount;
																if(balance_amount < 0)
																{
																	balance_amount = 0.0;
																}
																existing_bill.Bill_Date=bill_date;
																existing_bill.Vendor_Type="Employee Vendor";
																existing_bill.Employee_Vendor=employee_vendor_id;
																existing_bill.Display_Name_Vendor=employee_vendor_display;
																existing_bill.Vendor=null;
																existing_bill.Bill_Name="Offloading";
																bill_number = ifnull(existing_bill.Bill_Number,"");
																existing_bill.Bill_Total=offloading_total;
																existing_bill.Services_Total=offloading_total;
																existing_bill.Total_Amount=offloading_total;
																existing_bill.Amount_Due=offloading_total;
																existing_bill.Bill_Status="Draft";
																if(paid_amount <= 0)
																{
																	existing_bill.Payment_Status="Not Paid";
																}
																else if(balance_amount <= 0)
																{
																	existing_bill.Payment_Status="Paid";
																}
																else
																{
																	existing_bill.Payment_Status="Partially Paid";
																}
																bill_id = existing_bill.ID;
															}
															else
															{
																doc_key = Document_Key[Voucher_Type == "Offloading" && Document_Key_Status == "Active"];
																if(doc_key.ID == null)
																{
																	delivered_processing_ok = false;
																	info "Active Offloading Document Key was not found.";
																}
																else
																{
																	next_number = ifnull(doc_key.Next_Number,1);
																	max_number = ifnull(doc_key.Max_Number,99999);
																	if(next_number > max_number)
																	{
																		delivered_processing_ok = false;
																		info "Offloading bill numbers reached the limit.";
																	}
																	else
																	{
																		if(next_number < 10)
																		{
																			bill_number = "0000" + next_number;
																		}
																		else if(next_number < 100)
																		{
																			bill_number = "000" + next_number;
																		}
																		else if(next_number < 1000)
																		{
																			bill_number = "00" + next_number;
																		}
																		else if(next_number < 10000)
																		{
																			bill_number = "0" + next_number;
																		}
																		else
																		{
																			bill_number = next_number.toString();
																		}
																		bill_id = insert into Bill
																		[
																			Bill_Date=bill_date
																			Vendor_Type="Employee Vendor"
																			Employee_Vendor=employee_vendor_id
																			Display_Name_Vendor=employee_vendor_display
																			Bill_Name="Offloading"
																			Bill_Number=bill_number
																			Bill_Total=offloading_total
																			Services_Total=offloading_total
																			Total_Amount=offloading_total
																			Amount_Due=offloading_total
																			Amount_Paid=0.0
																			Bill_Status="Draft"
																			Payment_Status="Not Paid"
																			Added_User=zoho.loginuser
																		];
																		if(bill_id != null)
																		{
																			doc_key.Next_Number=next_number + 1;
																		}
																		else
																		{
																			delivered_processing_ok = false;
																		}
																	}
																}
															}
															if(bill_id != null)
															{
																truck_movement_display = ifnull(input.Display_Name_Voucher,"");
																for each  srv in input.Services
																{
																	if(srv.Service != null)
																	{
																		service_name = ifnull(srv.Service.Service_Name,"").trim();
																		if(service_name == "Offloading")
																		{
																			srv.Bill=bill_id;
																			srv.Display_Name_Bill="Offloading - " + bill_number;
																			srv.Truck_Movement_Voucher=input.ID;
																			srv.Display_Name_Voucher=truck_movement_display;
																		}
																	}
																}
															}
														}
													}
													// =================================================
													// B. EMPLOYEE PIECE RATE
													// =================================================
													employee_display = ifnull(input.Display_Name_Employee,"").trim();
													employee_id = null;
													if(employee_display != "")
													{
														employee_lookup_result = employee_management.employee.get_employee_by_display_name(employee_display);
														if(employee_lookup_result != null && ifnull(employee_lookup_result.get("ok"),false) == true)
														{
															employee_id = employee_lookup_result.get("employee_id");
														}
													}
													if(input.ID != null && employee_id != null)
													{
														truck_movement_display = ifnull(input.Display_Name_Voucher,"").trim();
														if(input.Line_Number != null)
														{
															if(truck_movement_display != "")
															{
																truck_movement_display = truck_movement_display + " - " + input.Line_Number.toString();
															}
															else
															{
																truck_movement_display = input.Line_Number.toString();
															}
														}
														movement_date = zoho.currentdate;
														if(input.Time_Start != null)
														{
															movement_date = input.Time_Start.toDate();
														}
														day_number = movement_date.getDayOfWeek();
														if(day_number == 1)
														{
															days_to_monday = -6;
														}
														else
														{
															days_to_monday = 2 - day_number;
														}
														week_date = movement_date.addDay(days_to_monday);
														week_number = week_date.getWeekOfYear();
														week_text = week_number.toString();
														if(week_number < 10)
														{
															week_text = "0" + week_text;
														}
														weekly_bill_number = week_date.getYear().toString() + " Week " + week_text;
														employee_weekly_bill = Bill[Employee_Vendor == employee_id && Bill_Number == weekly_bill_number && Vendor_Type == "Employee Vendor"];
														piece_rate_exists = false;
														for each  srv in input.Services
														{
															if(srv.Service != null && ifnull(srv.Service.Service_Name,"").trim() == "Employee Piece Rate")
															{
																piece_rate_exists = true;
															}
														}
														if(piece_rate_exists == true && employee_weekly_bill.ID == null)
														{
															delivered_processing_ok = false;
															info "Existing weekly Employee Bill was not found: " + weekly_bill_number;
														}
														else if(employee_weekly_bill.ID != null)
														{
															total_difference = 0.0;
															piece_rate_rows = 0;
															for each  srv in input.Services
															{
																if(srv.Service != null)
																{
																	service_name = ifnull(srv.Service.Service_Name,"").trim();
																	if(service_name == "Employee Piece Rate")
																	{
																		current_amount = round(ifnull(srv.Line_Total,0.0),2);
																		old_synced_amount = round(ifnull(srv.Last_Synced_Group_Amount,0.0),2);
																		line_difference = current_amount - old_synced_amount;
																		total_difference = total_difference + line_difference;
																		piece_rate_rows = piece_rate_rows + 1;
																	}
																}
															}
															if(piece_rate_rows > 0)
															{
																new_total_amount = round(ifnull(employee_weekly_bill.Total_Amount,0.0) + total_difference,2);
																employee_weekly_bill.Bill_Total=round(ifnull(employee_weekly_bill.Bill_Total,0.0) + total_difference,2);
																employee_weekly_bill.Services_Total=round(ifnull(employee_weekly_bill.Services_Total,0.0) + total_difference,2);
																employee_weekly_bill.Total_Amount=new_total_amount;
																employee_weekly_bill.Amount_Due=new_total_amount;
																amount_paid = ifnull(employee_weekly_bill.Amount_Paid,0.0);
																new_balance = new_total_amount - amount_paid;
																if(new_balance < 0)
																{
																	new_balance = 0.0;
																}
																//employee_weekly_bill.Balance_Due=round(new_balance,2);
																if(amount_paid <= 0)
																{
																	employee_weekly_bill.Payment_Status="Not Paid";
																}
																else if(new_balance <= 0)
																{
																	employee_weekly_bill.Payment_Status="Paid";
																}
																else
																{
																	employee_weekly_bill.Payment_Status="Partially Paid";
																}
																for each  srv in input.Services
																{
																	if(srv.Service != null && ifnull(srv.Service.Service_Name,"").trim() == "Employee Piece Rate")
																	{
																		current_amount = round(ifnull(srv.Line_Total,0.0),2);
																		srv.Bill=employee_weekly_bill.ID;
																		srv.Display_Name_Bill=employee_display + " - " + weekly_bill_number;
																		srv.Truck_Movement_Voucher=input.ID;
																		srv.Display_Name_Voucher=truck_movement_display;
																		srv.Last_Synced_Group_ID=employee_weekly_bill.ID;
																		srv.Last_Synced_Group_Amount=current_amount;
																	}
																}
															}
														}
													}
													// =================================================
													// C. WEIGH BRIDGE
													// =================================================
													has_weigh_bridge = false;
													for each  srv in input.Services
													{
														if(srv.Service != null && ifnull(srv.Service.Service_Name,"").trim() == "Weigh Bridge")
														{
															has_weigh_bridge = true;
														}
													}
