															{
																hamid_employee_id = hamid_result.get("employee_id");
																weigh_bridge_result = thisapp.services.recalculate_weekly_weigh_bridge(hamid_employee_id,input.Time_Start.toDate(),truck_plate);
																info weigh_bridge_result;
																if(weigh_bridge_result == null || ifnull(weigh_bridge_result.get("ok"),false) != true)
																{
																	delivered_processing_ok = false;
																}
															}
															else
															{
																delivered_processing_ok = false;
																info "Hamid Ssenoga - 50 was not found.";
															}
														}
													}
													// =================================================
													// D. LABOUR RECALCULATION
													// =================================================
													employee_display_name = ifnull(input.Display_Name_Employee,"").trim();
													labour_employee_id = null;
													if(employee_display_name != "")
													{
														labour_employee_result = employee_management.employee.get_employee_by_display_name(employee_display_name);
														if(labour_employee_result != null && ifnull(labour_employee_result.get("ok"),false) == true)
														{
															labour_employee_id = labour_employee_result.get("employee_id");
														}
													}
													if(labour_employee_id != null)
													{
														work_date = zoho.currentdate;
														if(input.Time_Start != null)
														{
															work_date = input.Time_Start.toDate();
														}
														labour_result = thisapp.labour.recalculate_truck_movement_labour(labour_employee_id,employee_display_name,work_date);
														info labour_result;
														if(ifnull(labour_result.get("ok"),false) != true)
														{
															delivered_processing_ok = false;
														}
													}
													else
													{
														delivered_processing_ok = false;
														info "Labour recalculation failed: employee could not be resolved from Display Name Employee.";
													}
													// =====================================================
													// BUILD BASIC DESCRIPTION FOR ALL SERVICE DETAILS
													// =====================================================
													movement_display = ifnull(input.Display_Name_Voucher,"").trim();
													truck_plate = ifnull(input.Number_Plate_Truck_Register,"").trim();
													employee_display = ifnull(input.Display_Name_Employee,"").trim();
													pickup_from = ifnull(input.Pick_Up_From,"").trim();
													delivery_to = ifnull(input.Delivery_To,"").trim();
													job_display = "";
													if(input.Job != null)
													{
														job_name_text = ifnull(input.Job.Job_Name,"").trim();
														job_number_text = ifnull(input.Job.Job_No,"").trim();
														if(job_name_text != "")
														{
															job_display = job_name_text;
														}
														else
														{
															job_display = job_number_text;
														}
													}
													movement_date = zoho.currentdate;
													if(input.Time_Start != null)
													{
														movement_date = input.Time_Start.toDate();
													}
													for each  srv in input.Services
													{
														if(srv.Service != null)
														{
															description_text = "";
															if(movement_display != "")
															{
																description_text = "Truck Movement Voucher: " + movement_display;
															}
															else
															{
																description_text = "Truck Movement Voucher: " + input.ID.toString();
															}
															if(input.Line_Number != null)
															{
